#pragma warning disable CA1725
using FluentValidation;
using MediatR;
using WhatsBiz.Application.Common.Exceptions;
using WhatsBiz.Application.Common.Interfaces;
namespace WhatsBiz.Application.Features.Inventory;
public sealed record BalanceDto(Guid InventoryBalanceId, Guid ProductId, string ProductCode, string ProductName, Guid WarehouseId, string WarehouseCode, string WarehouseName, Guid? ZoneId, string? ZoneCode, Guid? BinId, string? BinCode, string? BatchNo, string? SerialNo, decimal QuantityOnHand, decimal QuantityReserved, decimal QuantityAvailable, decimal AverageCost, decimal LastPurchaseCost, decimal StockValue, DateTimeOffset LastUpdated); public sealed record PagedBalances(IReadOnlyCollection<BalanceDto> Items, int TotalCount, int PageNumber, int PageSize); public sealed record TransactionLineDto(Guid TransactionDetailId, Guid ProductId, string ProductCode, string ProductName, string? BatchNo, string? SerialNo, decimal Quantity, decimal UnitCost, decimal TotalCost); public sealed record TransactionDto(Guid TransactionId, string TransactionNo, DateTimeOffset TransactionDate, string TransactionType, string? ReferenceType, Guid? ReferenceId, Guid WarehouseId, string WarehouseName, string? Remarks, string? CreatedBy, IReadOnlyCollection<TransactionLineDto> Details); public sealed record TransactionListDto(Guid TransactionId, string TransactionNo, DateTimeOffset TransactionDate, string TransactionType, string? ReferenceType, Guid WarehouseId, string WarehouseName, decimal TotalQuantity, decimal TotalCost); public sealed record PagedTransactions(IReadOnlyCollection<TransactionListDto> Items, int TotalCount, int PageNumber, int PageSize); public sealed record ReservationDto(Guid StockReservationId, string ReservationNo, Guid ProductId, Guid WarehouseId, decimal Quantity, decimal ReleasedQuantity, string ReservationReason, string? ReferenceType, Guid? ReferenceId, string Status, DateTimeOffset CreatedOn); public sealed record AdjustmentInput(Guid ProductId, Guid WarehouseId, Guid? ZoneId, Guid? BinId, string? BatchNo, string? SerialNo, decimal Quantity, decimal UnitCost, string AdjustmentType, string ReasonCode, string? Remarks); public sealed record TransferInput(Guid ProductId, Guid SourceWarehouseId, Guid DestinationWarehouseId, decimal Quantity, DateTimeOffset TransferDate, string? Remarks); public sealed record ReservationInput(string Action, Guid? StockReservationId, Guid? ProductId, Guid? WarehouseId, decimal Quantity, string? ReservationReason, string? ReferenceType, Guid? ReferenceId); public sealed record OperationDto(Guid OperationId, Guid TransactionId, string Number); public sealed record SummaryDto(decimal TotalQuantity, decimal TotalStockValue, decimal ReservedStock, int LowStockProducts, int OutOfStockProducts);
public sealed record GetBalances(string? Search, Guid? WarehouseId, Guid? ProductId, int PageNumber, int PageSize) : IRequest<PagedBalances>; public sealed record GetTransactions(string? Search, Guid? WarehouseId, string? TransactionType, DateTimeOffset? From, DateTimeOffset? To, int PageNumber, int PageSize) : IRequest<PagedTransactions>; public sealed record GetTransaction(Guid Id) : IRequest<TransactionDto>; public sealed record GetReservations(Guid? WarehouseId, Guid? ProductId) : IRequest<IReadOnlyCollection<ReservationDto>>; public sealed record GetSummary(Guid? WarehouseId) : IRequest<SummaryDto>; public sealed record AdjustStock(AdjustmentInput Input) : IRequest<OperationDto>; public sealed record TransferStock(TransferInput Input) : IRequest<OperationDto>; public sealed record ReserveStock(ReservationInput Input) : IRequest<OperationDto>; public sealed record ExportBalances(string? Search, Guid? WarehouseId, Guid? ProductId) : IRequest<byte[]>;
public sealed class AdjustmentValidator : AbstractValidator<AdjustStock> { public AdjustmentValidator() { RuleFor(x => x.Input.ProductId).NotEmpty(); RuleFor(x => x.Input.WarehouseId).NotEmpty(); RuleFor(x => x.Input.Quantity).GreaterThan(0); RuleFor(x => x.Input.UnitCost).GreaterThanOrEqualTo(0); RuleFor(x => x.Input.AdjustmentType).Must(x => x is "INCREASE" or "DECREASE"); RuleFor(x => x.Input.ReasonCode).NotEmpty().MaximumLength(50); } }
public sealed class TransferValidator : AbstractValidator<TransferStock> { public TransferValidator() { RuleFor(x => x.Input.ProductId).NotEmpty(); RuleFor(x => x.Input.SourceWarehouseId).NotEmpty(); RuleFor(x => x.Input.DestinationWarehouseId).NotEmpty().NotEqual(x => x.Input.SourceWarehouseId); RuleFor(x => x.Input.Quantity).GreaterThan(0); } }
public sealed class ReservationValidator : AbstractValidator<ReserveStock> { public ReservationValidator() { RuleFor(x => x.Input.Action).Must(x => x is "RESERVE" or "RELEASE"); RuleFor(x => x.Input.Quantity).GreaterThan(0); RuleFor(x => x.Input.ProductId).NotEmpty().When(x => x.Input.Action == "RESERVE"); RuleFor(x => x.Input.WarehouseId).NotEmpty().When(x => x.Input.Action == "RESERVE"); RuleFor(x => x.Input.StockReservationId).NotEmpty().When(x => x.Input.Action == "RELEASE"); } }
public sealed class InventoryHandlers(IInventoryRepository repository, IInventoryService inventory, IInventorySpreadsheetService spreadsheet, ICurrentUserService user) : IRequestHandler<GetBalances, PagedBalances>, IRequestHandler<GetTransactions, PagedTransactions>, IRequestHandler<GetTransaction, TransactionDto>, IRequestHandler<GetReservations, IReadOnlyCollection<ReservationDto>>, IRequestHandler<GetSummary, SummaryDto>, IRequestHandler<AdjustStock, OperationDto>, IRequestHandler<TransferStock, OperationDto>, IRequestHandler<ReserveStock, OperationDto>, IRequestHandler<ExportBalances, byte[]> { public async Task<PagedBalances> Handle(GetBalances q, CancellationToken t) { var (x, n) = await repository.Balances(q.Search, q.WarehouseId, q.ProductId, q.PageNumber, q.PageSize, t); return new(x.Select(b => new BalanceDto(b.InventoryBalanceId, b.ProductId, b.Product.ProductCode, b.Product.ProductName, b.WarehouseId, b.Warehouse.WarehouseCode, b.Warehouse.WarehouseName, b.ZoneId, b.Zone?.ZoneCode, b.BinId, b.Bin?.BinCode, b.BatchNo, b.SerialNo, b.QuantityOnHand, b.QuantityReserved, b.QuantityAvailable, b.AverageCost, b.LastPurchaseCost, b.QuantityOnHand * b.AverageCost, b.LastUpdated)).ToArray(), n, q.PageNumber, q.PageSize); } public async Task<PagedTransactions> Handle(GetTransactions q, CancellationToken t) { var (x, n) = await repository.Transactions(q.Search, q.WarehouseId, q.TransactionType, q.From, q.To, q.PageNumber, q.PageSize, t); return new(x.Select(a => new TransactionListDto(a.TransactionId, a.TransactionNo, a.TransactionDate, a.TransactionType, a.ReferenceType, a.WarehouseId, a.Warehouse.WarehouseName, a.Details.Sum(d => d.Quantity), a.Details.Sum(d => d.TotalCost))).ToArray(), n, q.PageNumber, q.PageSize); } public async Task<TransactionDto> Handle(GetTransaction q, CancellationToken t) { var x = await repository.Transaction(q.Id, t) ?? throw new EntityNotFoundException("Inventory transaction not found."); return new(x.TransactionId, x.TransactionNo, x.TransactionDate, x.TransactionType, x.ReferenceType, x.ReferenceId, x.WarehouseId, x.Warehouse.WarehouseName, x.Remarks, x.CreatedBy, x.Details.Select(d => new TransactionLineDto(d.TransactionDetailId, d.ProductId, d.Product.ProductCode, d.Product.ProductName, d.BatchNo, d.SerialNo, d.Quantity, d.UnitCost, d.TotalCost)).ToArray()); } public async Task<IReadOnlyCollection<ReservationDto>> Handle(GetReservations q, CancellationToken t) => (await repository.Reservations(q.WarehouseId, q.ProductId, t)).Select(x => new ReservationDto(x.StockReservationId, x.ReservationNo, x.ProductId, x.WarehouseId, x.Quantity, x.ReleasedQuantity, x.ReservationReason, x.ReferenceType, x.ReferenceId, x.Status, x.CreatedOn)).ToArray(); public async Task<SummaryDto> Handle(GetSummary q, CancellationToken t) { var x = await repository.Summary(q.WarehouseId, t); return new(x.TotalQuantity, x.TotalStockValue, x.ReservedStock, x.LowStockProducts, x.OutOfStockProducts); } public async Task<OperationDto> Handle(AdjustStock q, CancellationToken t) { var i = q.Input; var x = await inventory.Adjust(new(i.ProductId, i.WarehouseId, i.ZoneId, i.BinId, i.BatchNo, i.SerialNo, i.Quantity, i.UnitCost, i.AdjustmentType, i.ReasonCode, i.Remarks, user.Username), t); return new(x.OperationId, x.TransactionId, x.Number); } public async Task<OperationDto> Handle(TransferStock q, CancellationToken t) { var i = q.Input; var x = await inventory.Transfer(new(i.ProductId, i.SourceWarehouseId, i.DestinationWarehouseId, i.Quantity, i.TransferDate, i.Remarks, user.Username), t); return new(x.OperationId, x.TransactionId, x.Number); } public async Task<OperationDto> Handle(ReserveStock q, CancellationToken t) { var i = q.Input; var x = await inventory.Reserve(new(i.Action, i.StockReservationId, i.ProductId, i.WarehouseId, i.Quantity, i.ReservationReason, i.ReferenceType, i.ReferenceId, user.Username), t); return new(x.OperationId, x.TransactionId, x.Number); } public async Task<byte[]> Handle(ExportBalances q, CancellationToken t) { var (x, _) = await repository.Balances(q.Search, q.WarehouseId, q.ProductId, 1, 10000, t); return spreadsheet.ExportBalances(x); } }
